import React from "react";
import "../theme.css";

function ChartCard({ title, children, subtitle }) {
  return (
    <div
      style={{
        background: "var(--surface)",
        border: "1px solid var(--border)",
        borderRadius: "18px",
        padding: "20px",
        boxShadow: "var(--shadow-sm)"
      }}
    >
      <div style={{ marginBottom: "14px" }}>
        <h4 style={{ margin: 0, color: "var(--text)", fontSize: "18px" }}>{title}</h4>
        {subtitle ? (
          <p style={{ margin: "6px 0 0", color: "var(--muted)", fontSize: "13px" }}>
            {subtitle}
          </p>
        ) : null}
      </div>

      <div
  style={{
    width: "100%",
    height: window.innerWidth < 600 ? "240px" : "300px"
  }}
>
        {children}
      </div>
    </div>
  );
}

export default ChartCard;
